const daily = $input.first().json;
const baseContext = $('Webhook').item.json.base_context;

const fechaHoy = new Date().toLocaleString('es-MX', {
  timeZone: 'America/Mexico_City',
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

const hasDailyData = daily && daily.loan_id && daily.user_id;

let contextBlock;
let dailyAvailable = false;

if (hasDailyData) {
  dailyAvailable = true;

  const dtd = daily.days_to_due_date;
  let dpdLabel;
  if (dtd > 0) {
    dpdLabel = `${dtd} día${dtd === 1 ? '' : 's'} de atraso`;
  } else if (dtd === 0) {
    dpdLabel = `hoy vence`;
  } else {
    dpdLabel = `faltan ${Math.abs(dtd)} día${Math.abs(dtd) === 1 ? '' : 's'} para vencer`;
  }

  const inAgency = daily.in_coll_agency || daily.in_findemo_agency || daily.in_external_coll_agency;

  // === NÚCLEO — siempre presente ===
  let lines = [
    `Hoy: ${fechaHoy}`,
    `Cliente: ${daily.first_name} | Préstamo #${daily.loan_number} | Tipo: ${daily.loan_type}`,
    `CLABE: ${daily.clabe} | Banco: ${daily.banco} | Ben: EMPRESA DEMO`,
    `Estado: ${dpdLabel} | Segmento: ${daily.coll_segment}`,
    `Pago semanal: $${daily.weekly_payment} | Para liquidar todo: $${daily.total_amount_to_paid} | Próximo pago: $${daily.next_due_amount}`,
  ];

  // === MULTAS — solo si hay ===
  if ((daily.due_late_fees || 0) > 0) {
    lines.push(`Multas acumuladas: $${daily.due_late_fees}`);
  }

  // === APLAZAMIENTO — solo si tiene disponibles O tiene uno pendiente ===
  if (daily.skip_payments_available > 0 || daily.pending_skip_activation) {
    let skipLine = `Aplazamiento: ${daily.skip_payments_available} disponible(s), fee $${daily.skip_fee || 0}`;
    if (daily.pending_skip_activation) {
      skipLine += ` | ⚠️ Pendiente de activar (${daily.days_to_pay_skip_fee} días para pagar fee)`;
    }
    lines.push(skipLine);
  }

  // === PROMESA DE PAGO — solo si tiene activa ===
  if (daily.active_promise) {
    lines.push(`Promesa activa: $${daily.promise_amount} para ${daily.promise_due_date} (${daily.days_to_promise} días restantes)`);
  }

  // === DESCUENTO DE CAMPAÑA — solo si hay ===
  if (daily.descuento) {
    lines.push(`Descuento campaña: paga $${daily.monto_campana} (ahorras $${daily.monto_descuento})`);
  }

  // === CASHBACK — solo si es TU y tiene saldo ===
  if ((daily.cashback_pool || 0) > 0) {
  lines.push(`Cashback disponible: $${daily.cashback_pool}`);
}

  // === REFINANCE — solo si ya lo usó (dato relevante para no ofrecerlo de nuevo) ===
  if (daily.refinanced) {
    lines.push(`Refinanciamiento: ya utilizado`);
  }

  // === AGENCIA — alerta crítica ===
  if (inAgency) {
    lines.push(`⚠️ ESCALAR INMEDIATAMENTE: cliente en agencia de cobranza`);
  }

  // === USER ID — solo para que el agente pueda hacer queries si necesita ===
  lines.push(`User ID (interno, no compartir): ${daily.user_id}`);

  contextBlock = lines.join('\n');

} else {
  // Sin datos de warehouse: fallback mínimo
  contextBlock = [
    `Hoy: ${fechaHoy}`,
    `Cliente: ${baseContext.first_name || 'no disponible'} | Préstamo #${baseContext.loan_number}`,
    `CLABE: ${baseContext.user_clabe || 'no disponible'}`,
    `⚠️ Sin datos de cobranza actualizados. Para montos o atrasos: pide al cliente revisar su app o transfiere a agente.`,
    `User ID (interno): ${baseContext.user_id}`,
  ].join('\n');
}

return [{
  json: {
    route_type: 'ACTIVE_LOAN',
    daily_available: dailyAvailable,
    context_block: contextBlock,
    raw_daily: hasDailyData ? daily : null,
    base_context: baseContext,
    should_escalate: hasDailyData && (daily.in_coll_agency || daily.in_findemo_agency || daily.in_external_coll_agency)
  }
}];

// MERGE DE ETIQUETAS
// Conserva manuales + agrega las del bot
const armar = $('armar_etiquetas').item.json;
const nuevas = armar.labels_to_apply || [];
const ownedByBot = armar.bot_owned_labels || [];

const respuestaChatwoot = $('get_etiquetas_actuales').item.json;
const existentes = respuestaChatwoot.payload || [];

// Manuales = las que NO están en el catálogo del bot
const manuales = existentes.filter(l => !ownedByBot.includes(l));

// Final = manuales preservadas + nuevas del bot (dedup)
const final = [...new Set([...manuales, ...nuevas])];

return [{
  json: {
    ...$json,
    labels: final,
    labels_preserved_manual: manuales,
    labels_added_by_bot: nuevas
  }
}];

const daily = $('get_daily_collections').item.json;
const user = $('Webhook').item.json; // viene de CLASSIFICATION con datos del query principal

const labels = [];

// === Estatus de cobranza (mutuamente excluyente) ===
const seg = (daily.coll_segment || '').toUpperCase();
if (seg === 'REMINDER') {
  labels.push('reminder');
} else if (seg === 'PAYDAY') {
  labels.push('payday');
} else if (seg === 'DEFAULTER') {
  labels.push('defaulter');
  // DPD específico
  const dpd = -daily.days_to_due_date; // si days_to_due_date = -2, dpd = 2
  if (dpd === 1) labels.push('1_dpd');
  else if (dpd === 2) labels.push('2_dpd');
  else if (dpd === 3) labels.push('3_dpd');
}

// === Tipo de préstamo (mutuamente excluyente) ===
const loanType = (daily.loan_type || daily.application_type || '').toUpperCase();
if (loanType === 'FT' || loanType === 'NEW') {
  labels.push('ft');
} else if (loanType === 'TU' || loanType === 'TOPUP') {
  labels.push('tu');
}

// === Estados especiales (combinables) ===
if (daily.active_promise) labels.push('promise_active');
if (daily.refinanced) labels.push('refinance');

// Skip: ajustar según defina el equipo de cobranza
if (daily.skip_in_last_7_days || daily.pending_skip_activation) {
  labels.push('skip_active');
}

// recent_disbursed solo si tienes disbursal_date en este contexto
// (puede venir del query principal, no de daily)

return [{ json: { ...$json, labels_to_apply: labels } }];
